      "desc_ru": "Burp Suite extensions (Autorize, JWT Editor, InQL) — Не отдельные продукты, а расширения из BApp Store внутри уже установленного Burp: Autorize автоматически переигрывает перехваченные запросы с сессией менее привилегированного пользователя и подсвечивает случаи идентичного ответа (то есть отсутствие проверки авторизации — прямая находка BOLA); JWT Editor облегчает манипуляцию JWT-токенами (смену алгоритма, полезной нагрузки); InQL специализируется на интроспекции и построении карты GraphQL-схемы для последующего ручного тестирования.",
