      "mitre": null,
      "code": "0022",
      "desc_en": "Checkov — As of 2026, the de facto leader of the category, especially after Terrascan was archived and tfsec was frozen. The key technical differentiator is graph-based analysis: the tool understands not only individual resource attributes (whether an S3 bucket is encrypted) but also relationships between resources (whether a specific internet gateway can actually reach that bucket through route tables) — catching an entire class of errors invisible to simple attribute scanners. More than 1,000 built-in policies covering CIS, PCI DSS, SOC 2, NIST, and HIPAA out of the box, with automatic mapping of findings to the specific required control — convenient when security and compliance teams must work from the same report.",
      "desc_ru": "Checkov — На 2026 год фактический лидер категории, особенно после архивации Terrascan и заморозки tfsec. Ключевое технологическое отличие — граф-based анализ: инструмент понимает не только отдельные атрибуты ресурса (зашифрован ли S3-бакет), но и связи между ресурсами (может ли конкретный интернет-гейтвей реально достучаться до этого бакета через таблицы маршрутизации) — это ловит целый класс ошибок, невидимых для простых сканеров атрибутов. Более 1000 встроенных политик, покрывающих CIS, PCI DSS, SOC 2, NIST, HIPAA \"из коробки\", с автоматическим маппингом находок на конкретный требуемый контроль — удобно, когда security и compliance-команды должны работать с одним и тем же отчётом.",
      "usage_en": "Typical use: checkov -d infra/ --framework terraform. Install: `pip install checkov`, запуск `checkov -d ./terraform`; так как написан на Python, немного тяжелее в установке/зависимостях, чем Go-based конкуренты вроде tfsec.",
      "usage_ru": "Типичное использование: checkov -d infra/ --framework terraform. Установка: `pip install checkov`, запуск `checkov -d ./terraform`; так как написан на Python, немного тяжелее в установке/зависимостях, чем Go-based конкуренты вроде tfsec.",
