      "desc_en": "Contrast Assess — Pioneer and, in effect, inventor of the IAST/RASP category as a commercial product. Works via an agent embedded in the application runtime (Java, .NET, Node.js, Python, Ruby) that observes real data flow through the code while your own functional/integration tests run — delivering SAST-level precision (exact code line) plus DAST context (whether data actually reaches the vulnerable sink at execution time), with notably fewer false positives than pure SAST. There is a free Community Edition (1 application, up to 5 users, some enterprise features disabled) — a good way to try the technology without budget.",
      "desc_ru": "Contrast Assess — Пионер и, по сути, изобретатель категории IAST/RASP как коммерческого продукта. Работает через агент, встраиваемый в рантайм приложения (Java, .NET, Node.js, Python, Ruby), который наблюдает за реальным прохождением данных через код во время выполнения ваших же функциональных/интеграционных тестов — это даёт точность SAST (точная строка кода) плюс контекст DAST (реально ли данные достигают уязвимого места при исполнении), с заметно меньшим числом false positive, чем у чистого SAST. Есть бесплатная Community Edition (1 приложение, до 5 пользователей, часть enterprise-фич отключена) — хороший способ попробовать технологию без бюджета.",
