      "code": "0031",
      "desc_en": "Cosign + Sigstore — Keyless signing of container images and arbitrary artifacts via a short-lived certificate issued after OIDC authentication (Fulcio is the certificate authority that issues short-lived certificates; Rekor is the public immutable transparency log of all signatures), without the need to manage long-lived private keys manually — substantially reduces the operational complexity of PKI for teams that want to sign releases but are not ready to maintain their own key infrastructure.",
      "desc_ru": "Cosign + Sigstore — Keyless-подпись контейнерных образов и произвольных артефактов через временный сертификат, выданный по факту OIDC-аутентификации (Fulcio — центр сертификации, выдающий краткоживущие сертификаты; Rekor — публичный неизменяемый transparency log всех подписей), без необходимости управлять долгоживущими приватными ключами вручную — существенно снижает операционную сложность PKI для команд, которые хотят подписывать релизы, но не готовы содержать собственную инфраструктуру ключей.",
      "usage_en": "Typical use: cosign verify --key cosign.pub myregistry/app:1.0. Install: `brew install cosign`, подпись образа в keyless-режиме: `cosign sign myrepo/myapp:latest`.",
      "usage_ru": "Типичное использование: cosign verify --key cosign.pub myregistry/app:1.0. Установка: `brew install cosign`, подпись образа в keyless-режиме: `cosign sign myrepo/myapp:latest`.",
      "example": "cosign verify --key cosign.pub myregistry/app:1.0",
      "install": "`brew install cosign`, подпись образа в keyless-режиме: `cosign sign myrepo/myapp:latest`.",
