      "desc_ru": "Coverity — Премиальный enterprise-SAST, исторически силён в C/C++ и embedded-разработке (авиация, автомобилестроение, медтех), где цена ошибки особенно высока. Известен очень низким false positive rate благодаря глубокому межпроцедурному анализу — команды тратят меньше времени на разбор шума, но платят за это заметно более высокой ценой лицензии и сложностью настройки инфраструктуры (нужен отдельный build-сервер Coverity Connect).",
