      "url": "https://falco.org/",
      "track": "appsec",
      "category": "runtime",
      "mitre": null,
      "code": "0045",
      "desc_en": "Falco — The de facto standard for runtime detection of anomalous behavior in containers/Kubernetes based on eBPF (a low-level Linux kernel technology for safe monitoring of system calls without modifying the kernel). Originally created by Sysdig and donated to the CNCF, so it sits \"under the hood\" of many commercial CNAPP platforms (including Sysdig Secure). Detects suspicious patterns in real time: an unexpected shell inside a container, attempts to read secrets off-purpose, anomalous network connections.",
      "desc_ru": "Falco — Стандарт де-факто для рантайм-детекта аномального поведения в контейнерах/Kubernetes на основе eBPF (низкоуровневая технология ядра Linux для безопасного мониторинга системных вызовов без модификации ядра). Изначально создан компанией Sysdig и передан в CNCF, поэтому лежит \"под капотом\" у многих коммерческих CNAPP-платформ (включая Sysdig Secure). Детектирует подозрительные паттерны в реальном времени: неожиданный shell внутри контейнера, попытки чтения секретов не по назначению, аномальные сетевые соединения.",
      "usage_en": "Typical use: helm install falco falcosecurity/falco. Install: `helm install falco falcosecurity/falco -n falco --create-namespace` для развёртывания в Kubernetes-кластере.",
      "usage_ru": "Типичное использование: helm install falco falcosecurity/falco. Установка: `helm install falco falcosecurity/falco -n falco --create-namespace` для развёртывания в Kubernetes-кластере.",
      "example": "helm install falco falcosecurity/falco",
      "install": "`helm install falco falcosecurity/falco -n falco --create-namespace` для развёртывания в Kubernetes-кластере.",
      "tags": "appsec,cwpp,handbook,k8s,runtime"
