      "desc_ru": "GitGuardian — Enterprise-платформа с уникальной способностью мониторить публичный GitHub в реальном времени на предмет утечки секретов вашей организации (даже случайно закоммиченных во внешние/личные репозитории сотрудников) — то, что ни один локальный open-source сканер сделать в принципе не может. ggshield — CLI-клиент, который можно использовать локально/в CI независимо от подписки на полную платформу. Бесплатный тир доступен для команд до 25 разработчиков.",
