      "desc_en": "GitHub Secret Scanning — A native feature of the GitHub platform itself, and push protection literally blocks a git push with a detected secret before it ever reaches the remote repository and its history — preventive protection, not post-facto detection. Works free for public repositories; for private ones it requires a GitHub Advanced Security license.",
      "desc_ru": "GitHub Secret Scanning — Нативная функция самой платформы GitHub, причём push protection буквально блокирует git push с обнаруженным секретом ещё до того, как он попадёт в удалённый репозиторий и его историю — превентивная защита, а не постфактум-детект. Для публичных репозиториев работает бесплатно, для приватных требует лицензии GitHub Advanced Security.",
