      "desc_en": "in-toto — A framework that verifies the integrity of every individual step in the software supply chain (from commit to final deploy) via cryptographically signed metadata at each stage — allows proving that the final artifact truly went through exactly those steps (build, tests, review) that were intended, and was not substituted at some intermediate stage.",
