      "desc_en": "Semgrep — A next-generation static analyzer that analyzes the AST (abstract syntax tree) of code rather than simply searching with regex. Rules are written in its own declarative syntax that resembles the code itself, which makes it possible to write custom checks in literally 10 minutes without deep knowledge of parsing theory. The Community version is fully free and covers most languages (Python, JS/TS, Go, Java, PHP, and others); Pro/Enterprise add cross-file taint analysis, secrets detection, and finding prioritization. An excellent first SAST for a team — low barrier to entry, fast scans (seconds to minutes), and fits well into pre-commit, CI, and the IDE.",
      "desc_ru": "Semgrep — Статический анализатор нового поколения, который анализирует AST (абстрактное синтаксическое дерево) кода, а не просто ищет по regex. Правила пишутся на собственном декларативном синтаксисе, похожем на сам код, что позволяет писать кастомные проверки буквально за 10 минут без глубокого знания теории парсинга. Community-версия полностью бесплатна и покрывает большинство языков (Python, JS/TS, Go, Java, PHP и др.), Pro/Enterprise добавляют межфайловый taint-анализ, secrets-детект и приоритизацию находок. Отлично подходит как первый SAST для команды — низкий порог входа, быстрые сканы (секунды-минуты), хорошо ложится и в pre-commit, и в CI, и в IDE.",
