      "desc_ru": "Snyk Open Source — Часть коммерческой платформы Snyk, известна лучшим в индустрии developer experience: автоматические pull request'ы с исправлением уязвимой зависимости, приоритизация находок по реальной эксплуатируемости (а не только по CVSS-скору), полированные IDE-плагины.",
      "usage_en": "Typical use: npm install -g snyk. Install: `npm install -g snyk`, `snyk auth`, затем `snyk test` в корне проекта; бесплатный тир доступен для небольших команд/личных проектов.",
