      "track": "appsec",
      "category": "sast",
      "mitre": null,
      "code": "0105",
      "desc_en": "SonarQube — Originally a code quality tool (code duplication, code smells, test coverage) that over recent years has grown into a full security solution with the Advanced Security product. Provides taint analysis (tracking data flow from an untrusted source to a dangerous sink) and secrets detection in the same dashboard where developers already review quality metrics — this reduces adoption resistance because a separate \"security-only\" tool is not needed. A strong fit for organizations that already use SonarQube for quality gates and want to add security without a new vendor.",
      "desc_ru": "SonarQube — Изначально инструмент для code quality (дублирование кода, code smells, покрытие тестами), который за последние годы дорос до полноценного security-решения с продуктом Advanced Security. Даёт taint-анализ (отслеживание потока данных от небезопасного источника до опасного использования) и secrets-детект прямо в том же дашборде, где разработчики уже смотрят метрики качества — это снижает сопротивление внедрению, потому что не нужен отдельный инструмент \"только для безопасности\". Хорошо подходит организациям, которые уже используют SonarQube для quality gates и хотят добавить security без нового вендора.",
      "usage_en": "Typical use: sonar-scanner -Dsonar.projectKey=myapp -Dsonar.sources=src. Install: `docker run -d -p 9000:9000 sonarqube:community` для сервера, плюс `sonar-scanner` CLI в CI-пайплайне для отправки результатов анализа.",
      "usage_ru": "Типичное использование: sonar-scanner -Dsonar.projectKey=myapp -Dsonar.sources=src. Установка: `docker run -d -p 9000:9000 sonarqube:community` для сервера, плюс `sonar-scanner` CLI в CI-пайплайне для отправки результатов анализа.",
      "example": "sonar-scanner -Dsonar.projectKey=myapp -Dsonar.sources=src",
      "install": "`docker run -d -p 9000:9000 sonarqube:community` для сервера, плюс `sonar-scanner` CLI в CI-пайплайне для отправки результатов анализа.",
      "tags": "appsec,ci,handbook,quality-gate,sast"
