      "code": "0109",
      "desc_en": "Syft (Anchore) — an SBOM generator (CycloneDX/SPDX) from an image, filesystem, or archive; often used together with Grype. Grype specializes only in detecting known CVEs (no IaC/secrets, but very accurate version matching with a low false-positive rate thanks to the curated grype-db database), while Syft is a separate but closely related SBOM generation tool. Because both use their own database distinct from Trivy's, practitioner teams often run Trivy and Grype together on critical images — discrepancies between two independent engines catch more real CVEs than either tool alone.",
      "desc_ru": "Syft (Anchore) — генератор SBOM (CycloneDX/SPDX) из образа, FS или архива; часто используется вместе с Grype. Grype специализируется только на детекте известных CVE (без IaC/secrets, зато очень точное сопоставление версий с низким false positive за счёт кураторской базы grype-db), а Syft — отдельный, но тесно связанный инструмент генерации SBOM. Так как оба используют собственную базу данных, отличную от Trivy, практикующие команды часто гоняют Trivy и Grype вместе на критичных образах — расхождения между двумя независимыми движками ловят больше реальных CVE, чем любой один инструмент.",
      "usage_en": "Typical use: syft myimage:latest -o spdx-json. Install: `brew install syft`, генерация: `syft myapp:latest -o cyclonedx-json > sbom.json`.",
      "usage_ru": "Типичное использование: syft myimage:latest -o spdx-json. Установка: `brew install syft`, генерация: `syft myapp:latest -o cyclonedx-json > sbom.json`.",
