      "mitre": null,
      "code": "1003",
      "desc_en": "Veracode Static Analysis — Unique feature: analyzes compiled bytecode/binaries rather than source code. This solves a practical problem — you can assess the security of third-party or acquired (M&A) software even without access to its source, which makes the tool especially useful for due diligence and vendor audits. Supports 30+ languages (Java, .NET, JavaScript, Python, PHP, Ruby, C/C++, Go, Kotlin, Swift, and others); analysis quality for Java/.NET is traditionally considered its strongest side. Has FedRAMP Moderate ATO and a full set of compliance certifications (SOC 2, ISO 27001, HIPAA, PCI DSS 4.0), which matters for regulated industries.",
      "desc_ru": "Veracode Static Analysis — Уникальная особенность: анализирует не исходный код, а скомпилированный байткод/бинарник. Это решает практическую проблему — можно проверить безопасность стороннего или купленного (M&A) софта, даже не имея доступа к его исходникам, что делает инструмент особенно полезным при due diligence и аудите вендоров. Поддерживает 30+ языков (Java, .NET, JavaScript, Python, PHP, Ruby, C/C++, Go, Kotlin, Swift и др.), качество анализа для Java/.NET традиционно считается сильнейшей стороной. Есть FedRAMP Moderate ATO и полный набор compliance-сертификаций (SOC 2, ISO 27001, HIPAA, PCI DSS 4.0), что важно для регулируемых индустрий.",
      "usage_en": "Install: облачная платформа Veracode, загрузка скомпилированного артефакта через веб-интерфейс, IDE-плагин или CLI-агент; каждое приложение лицензируется отдельно, что усложняет ценообразование для микросервисных архитектур.",
