      "id": "wiz",
      "name": "Wiz",
      "url": "https://www.wiz.io/",
      "track": "appsec",
      "category": "cspm",
      "mitre": null,
      "code": "1044",
      "desc_en": "Wiz — Built around a Security Graph that visualizes \"toxic combinations\": for example, a publicly accessible resource + a known vulnerability on it + excessive IAM permissions on its role = a concrete, actually traversable attack path, not three separate unrelated warnings. A fully agentless model (reading snapshots via cloud APIs) enables lightning-fast deployment without installing anything on workloads, but at the cost of snapshots being taken on an interval (typically 4–24 hours) — there is an inevitable \"blind\" window between scans for fast attacks that occur and complete between snapshots. Acquired by Google for roughly $32 billion in March 2025, which raises questions among some multi-cloud customers about future parity of AWS/Azure support relative to Google Cloud.",
      "desc_ru": "Wiz — Построен вокруг Security Graph, визуализирующего \"toxic combinations\": например, публично доступный ресурс + известная уязвимость на нём + избыточные IAM-права у его роли = конкретный, реально проходимый путь атаки, а не три отдельных не связанных предупреждения. Полностью agentless-модель (чтение снапшотов через облачные API) даёт молниеносное развёртывание без установки чего-либо на рабочие нагрузки, но ценой того, что снапшоты снимаются с интервалом (обычно 4-24 часа) — есть неизбежный \"слепой\" промежуток между сканами для быстрых атак, произошедших и завершившихся между снимками. Приобретён Google примерно за $32 млрд в марте 2025, что вызывает у части мультиклаудных клиентов вопросы о будущем паритете поддержки AWS/Azure относительно Google Cloud.",
