      "desc_ru": "OWASP Amass строит карту external attack surface: passive/active DNS, brute, scraping, граф связей. Тяжелее Subfinder, но граф активов богаче (владение, related domains, ASN). Для программ, где глубина важнее скорости. Ставь в начало kill-chain: не найденный актив не протестируешь. Всегда dedupe output, аккуратно с wildcard, соблюдай rate limit и out-of-scope программы.",
