      "code": "0131",
      "desc_en": "dirsearch is a Python web path scanner with recursion, extensions, and rich built-in wordlists. Slightly slower than ffuf but convenient features (reports, exclude sizes, force extensions) make it popular for thorough content discovery on single hosts. Calibrate against a baseline response (size/words/status) before full-speed runs to cut false positives. Combine small high-signal wordlists first, then larger ones once filters are stable.",
