      "desc_ru": "gf — обёртка над grep с наборами паттернов для bug bounty (xss params, ssrf, interesting ext). Ускоряет triage огромных URL-листов из gau/wayback. Ставь в начало kill-chain: не найденный актив не протестируешь. Всегда dedupe output, аккуратно с wildcard, соблюдай rate limit и out-of-scope программы.",
