      "desc_ru": "Ghauri — продвинутый SQLi-тул с современной логикой детекта; полезен, когда sqlmap буксует на WAF/нестандартных endpoint’ах. Второй движок того же класса — сравнивай результаты, не верь одному сканеру. Сначала ручная аномалия (error/boolean/time), потом тяжёлая автоматизация. Throttle на prod; сначала read-only; в отчёте — СУБД и impact (read vs RCE).",
