      "desc_en": "Gobuster is a Go multi-mode brute-forcer: directory/file, DNS subdomains, virtual hosts, S3 buckets, GCS. Simple, stable and widely available on Kali. Less filter-fancy than ffuf, still excellent for DNS and classic dir busting. Calibrate against a baseline response (size/words/status) before full-speed runs to cut false positives. Combine small high-signal wordlists first, then larger ones once filters are stable.",
      "desc_ru": "Gobuster — multi-mode brute на Go: dirs/files, DNS, vhosts, S3, GCS. Простой, стабильный, есть в Kali. Меньше «магии» фильтров чем ffuf, отличен для DNS и классического dir busting. Калибруй baseline ответа (size/words/status) до full-speed, иначе утонешь в FP. Сначала короткие high-signal словари, потом большие — когда фильтры стабильны.",
