      "desc_en": "Gopherus generates gopher:// payloads to chain SSRF into attacks on internal services (Redis, MySQL, FastCGI, Memcached, SMTP). When SSRF allows non-HTTP schemes, these payloads can trigger RCE or data writes on misconfigured internal daemons. Prove outbound with OAST first, then escalate schemes and internal targets. Cloud metadata, link-local and gopher to Redis are high-value checks when the application trusts user-supplied URLs.",
      "desc_ru": "Gopherus генерирует gopher:// payloads для SSRF → internal (Redis, MySQL, FastCGI, Memcached, SMTP). Если SSRF пускает non-HTTP schemes, возможны RCE/запись на криво настроенных демонах. Сначала OAST (outbound), потом schemes и internal. Metadata, link-local, gopher→Redis — high-value, если приложение доверяет user URL.",
      "usage_en": "After SSRF confirmed with HTTP, test scheme support; generate service-specific payload.",
