      "desc_ru": "Masscan — асинхронный port scanner интернет-масштаба. Широкий discovery по многим IP, затем open ports в Nmap на versioning. Легко сделать шум — rate-limit обязательно. Scope и timing важны: агрессивный скан = IDS и ToS. Прогрессия (top ports → full); open ports всегда в version detection до exploitation.",
