      "code": "0147",
      "desc_en": "Metasploit Framework — The industry standard for vulnerability exploitation: a huge community-maintained library of ready, validated exploits, flexible payload and encoder generators, and the famous Meterpreter — an advanced payload for post-exploitation (credential harvesting, lateral movement, traffic tunneling). The open Community edition covers virtually all functionality needed for standard network pentests; the paid Pro edition adds a web UI, automated exploitation workflows, and more convenient reporting.",
      "desc_ru": "Metasploit Framework — Индустриальный стандарт эксплуатации уязвимостей: огромная поддерживаемая сообществом библиотека готовых, провалидированных эксплойтов, гибкие генераторы payload'ов и энкодеров, и знаменитый Meterpreter — продвинутый payload для пост-эксплуатации (сбор учётных данных, латеральное перемещение, туннелирование трафика). Открытая Community-версия покрывает практически весь функционал, нужный для стандартных сетевых пентестов; платная Pro-версия добавляет веб-интерфейс, автоматизированные workflow эксплуатации и более удобную отчётность.",
