      "desc_ru": "Nikto — Заслуженный ветеран категории, появился ещё в начале 2000-х. Проверяет веб-сервер на предмет опасных/устаревших файлов, известных уязвимых версий ПО и типичных конфигурационных проблем (директория листинг, дефолтные страницы). Уступает современным инструментам по глубине анализа и почти не понимает современные SPA-приложения, но остаётся полезным как быстрая первая проверка веб-сервера (\"low-hanging fruit\" сканер) перед более глубоким тестированием.",
