      "desc_ru": "OpenRedireX фаззит и валидирует open redirect (payloads + Location/meta). Redirect’ы кормят phishing и OAuth token theft; автоматизация ловит low-hanging fruit на больших URL-сетах. Комбинируй с соседними тулами в пайплайне, high-severity findings подтверждай вручную, веди заметки пригодные для нормального отчёта.",
      "usage_en": "Collect redirect-like params (url,next,return,redir); run payloads; verify browser behavior. Install: `npm install -g snyk`, `snyk auth`, затем `snyk test` в корне проекта.",
