      "desc_en": "ProjectDiscovery suite — Three tools from one ecosystem that work together as a reconnaissance pipeline: subfinder enumerates the target's subdomains, httpx checks which of the discovered hosts are actually \"alive\" and identifies the technology stack, katana crawls the found live hosts building a full map of the application — the result of this chain is then fed into Nuclei for targeted scanning.",
