      "desc_en": "sqlmap — The reference tool for automating detection and subsequent exploitation of SQL injections; supports virtually all common DBMSs (MySQL, PostgreSQL, MSSQL, Oracle, SQLite, and others) and all major techniques (union-based, error-based, boolean/time-based blind, out-of-band), including automated table enumeration and full data dumps.",
      "desc_ru": "sqlmap — Эталонный инструмент автоматизации детекта и последующей эксплуатации SQL-инъекций, поддерживает практически все распространённые СУБД (MySQL, PostgreSQL, MSSQL, Oracle, SQLite и другие) и все основные техники (union-based, error-based, boolean/time-based blind, out-of-band), включая автоматизацию enumeration таблиц и полного дампа данных.",
      "usage_en": "Typical use: sqlmap -r req.txt -p id --batch --dbs. Install: `git clone https://github.com/sqlmapproject/sqlmap.git`, запуск `python3 sqlmap.py -u \"http://target/page?id=1\"`; также доступен через `brew install sqlmap`.",
