      "desc_ru": "Wfuzz — гибкий Python-фаззер: несколько payload-наборов, encodings, сложные фильтры. Силён для param/header fuzzing и комбинаций (user×pass, path×ext), когда важнее гибкость, а не рекорд скорости. Калибруй baseline ответа (size/words/status) до full-speed, иначе утонешь в FP. Сначала короткие high-signal словари, потом большие — когда фильтры стабильны.",
