      "usage_ru": "Keywords компании; open buckets — только authorized. Установка: коммерческая подписка F5, разворачивается как модуль/прокси перед приложением. Установка: SaaS-консоль Prisma Cloud, для рантайм-защиты дополнительно разворачивается Defender-агент в кластере/на хостах. Установка: включается в портале Azure (Defender for Cloud → Environment settings → включить план), для AWS/GCP — через Environment settings → Add environment. Установка: `pip install c7n`, политики описываются в YAML-файле, запуск `custodian run -s output policy.yml`.",
