      "desc_ru": "Cobalt Strike — Премиальный коммерческий C2 (command-and-control) фреймворк специально для red team/adversary simulation, а не для обычного vulnerability-ориентированного пентеста. Ключевая фича — malleable C2 profiles, позволяющие маскировать сетевые индикаторы beacon-агента под конкретного реального threat actor, что даёт возможность тестировать не просто наличие уязвимостей, а реальную способность SOC-команды обнаружить и среагировать на конкретный, реалистичный сценарий атаки. Требует обязательной верификации организации-покупателя вендором Fortra; репутационные риски инструмента связаны исключительно со злоупотреблением утёкшими взломанными копиями, а не с легальным лицензированным использованием.",
