      "desc_en": "OpenVAS / Greenbone — A full-featured free alternative to Nessus with a large and actively updated check database, at the cost of a slightly less polished user interface and somewhat more labor-intensive initial setup of the scanning infrastructure.",
      "desc_ru": "OpenVAS / Greenbone — Полноценная бесплатная альтернатива Nessus с большой и активно обновляемой базой проверок, ценой чуть менее полированного пользовательского интерфейса и немного более трудоёмкой первоначальной настройки инфраструктуры сканирования.",
