      "usage_ru": "Типичное использование: gvm-start  # then open Greenbone web UI and create a task. Установка: `docker run -d -p 443:443 --name openvas mikesplain/openvas` для быстрого community-образа, либо полноценный официальный Greenbone Community Edition installer для продакшн-использования.",
