      "mitre": null,
      "code": "0245",
      "desc_en": "Dirb is a classic directory brute-forcer with recursive wordlists. Predecessor culture to gobuster/ffuf; still on many distros for simple content discovery. Calibrate against a baseline response (size/words/status) before full-speed runs to cut false positives. Combine small high-signal wordlists first, then larger ones once filters are stable.",
      "desc_ru": "Dirb — классический directory brute с рекурсивными словарями. Предшественник культуры gobuster/ffuf; всё ещё в дистрибутивах для простого discovery. Калибруй baseline ответа (size/words/status) до full-speed, иначе утонешь в FP. Сначала короткие high-signal словари, потом большие — когда фильтры стабильны.",
      "usage_en": "Quick path brute on lab web roots.",
