      "mitre": null,
      "code": "0246",
      "desc_en": "jwt_tool tests JSON Web Token implementations: alg:none, key confusion (RS→HS), kid injection, crack weak secrets, claim tampering, and more. Essential when APIs use JWT for sessions/authz. Always check algorithm confusion, weak HMAC secrets, and whether the server enforces audience/issuer/exp claims consistently.",
      "desc_ru": "jwt_tool тестирует JWT: alg:none, key confusion (RS→HS), kid injection, crack слабых секретов, подмена claims. Must-have, если API сидит на JWT. Всегда: algorithm confusion, слабый HMAC, и enforcement aud/iss/exp на сервере.",
