      "desc_en": "Wireshark — The standard graphical network traffic analyzer, dissecting packets in detail at all layers of the network stack (from Ethernet to application-layer protocols such as HTTP/DNS/TLS handshake) — indispensable for analyzing captured traffic, diagnosing network problems, and understanding the exact network behavior of an application.",
