      "desc_ru": "LitmusChaos — CNCF-graduated платформа хаос-инженерии для Kubernetes. Поставляется с 50+ готовыми экспериментами: pod delete, node drain, network partition, disk fill, CPU hog, container kill. Security-релевантность: валидирует, что RBAC-политики держатся при сбоях, секреты не утекают в crash-логи, а network policies блокируют непредусмотренные lateral-пути во время аутажей. ChaosHub предоставляет community-библиотеку экспериментов; результаты интегрируются с Prometheus/Grafana.",
