      "code": "1100",
      "desc_en": "Chaos Mesh — CNCF chaos engineering platform for Kubernetes with a rich web dashboard and fine-grained fault injection: PodChaos, NetworkChaos (packet loss/delay/duplicate/corrupt), DNSChaos, HTTPChaos (inject faults into HTTP requests/responses), IOChaos (filesystem fault injection), StressChaos, TimeChaos. HTTPChaos and DNSChaos are particularly valuable for security testing: simulate DNS hijacking, delayed auth calls, and corrupted API responses to verify that the application fails safely without exposing sensitive data.",
      "desc_ru": "Chaos Mesh — CNCF chaos-платформа для Kubernetes с web-дашбордом и точечной инъекцией сбоев: PodChaos, NetworkChaos (packet loss/delay/duplicate/corrupt), DNSChaos, HTTPChaos (фолты в HTTP req/resp), IOChaos (filesystem fault injection), StressChaos, TimeChaos. HTTPChaos и DNSChaos особенно ценны для security-тестирования: симулируй DNS-hijacking, задержку auth-вызовов и искажённые API-ответы для проверки безопасного fail-поведения без утечки sensitive-данных.",
