      "desc_en": "Dependency-Track — OWASP flagship SBOM intelligence platform that continuously analyzes SBOMs (CycloneDX, SPDX) against multiple vulnerability databases: NVD, OSV, GitHub Advisories, VulnDB. Goes beyond point-in-time scans: when a new CVE is published, it immediately surfaces all components affected across all your projects. Tracks component licenses (GPL contamination alerts), outdated components, and policy violations. Integrates with CI/CD via REST API; feeds findings to Defect Dojo, Jira, or webhooks.",
      "desc_ru": "Dependency-Track — OWASP-флагманская SBOM intelligence платформа с непрерывным анализом SBOM (CycloneDX, SPDX) против множества баз уязвимостей: NVD, OSV, GitHub Advisories, VulnDB. Выходит за рамки разовых сканов: при публикации нового CVE немедленно показывает все затронутые компоненты по всем проектам. Трекает лицензии компонентов (GPL-contamination alerts), устаревшие компоненты и policy violations. Интегрируется в CI/CD через REST API; отправляет findings в Defect Dojo, Jira или webhooks.",
