      "desc_ru": "OpenSSF Scorecard — автоматизированные метрики security-здоровья open-source проектов на GitHub/GitLab. Запускает 20+ проверок: Branch-Protection, Code-Review, Dependency-Update-Tool, Fuzzing, License, Pinned-Dependencies, SAST, Signed-Releases, Token-Permissions, Vulnerabilities, Binary-Artifacts. Оценка 0-10; каждая проверка взвешена. Критично для supply chain due diligence: перед подключением новой зависимости прогони scorecard — есть ли code review, branch protection, pinned actions. Интегрируется с GitHub Actions; выдаёт SARIF.",
